30: function detectDeliverableFormat(name: string, rawFormat?: string | null): DeliverableItem['format'] {
31:   const ext = name.includes('.') ? (name.split('.').pop()?.toLowerCase() ?? '') : '';
32:   const fmt = (rawFormat ?? '').toLowerCase();
33:   if (ext === 'md' || ext === 'markdown' || fmt === 'markdown') return 'markdown';
34:   if (ext === 'pdf' || fmt === 'pdf') return 'pdf';
35:   if (ext === 'docx' || fmt === 'docx') return 'docx';
36:   if (ext === 'xlsx' || ext === 'xlsm' || fmt === 'xlsx') return 'xlsx';
37:   if (ext === 'csv' || fmt === 'csv') return 'csv';
38:   if (['png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp', 'svg', 'ico'].includes(ext) || fmt === 'image') {
39:     return 'image';
40:   }
41:   if (ext === 'html' || ext === 'htm' || fmt === 'html') return 'html';
42:   return 'text';
43: }
