45: function formatFileSize(bytes: number): string {
46:   if (!Number.isFinite(bytes) || bytes < 0) return '0 B';
47:   if (bytes < 1024) return `${bytes} B`;
48:   if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
49:   return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
50: }
