57: function parseCsvLine(line: string, delimiter: string): string[] {
58:   const cells: string[] = [];
59:   let current = '';
60:   let inQuotes = false;
61:   for (let i = 0; i < line.length; i += 1) {
62:     const ch = line[i];
63:     if (ch === '"') {
64:       if (inQuotes && line[i + 1] === '"') {
65:         current += '"';
66:         i += 1;
67:       } else {
68:         inQuotes = !inQuotes;
69:       }
70:     } else if (ch === delimiter && !inQuotes) {
71:       cells.push(current.trim());
72:       current = '';
73:     } else {
74:       current += ch;
75:     }
76:   }
77:   cells.push(current.trim());
78:   return cells;
79: }
