81: function parseSpreadsheetPreview(text: string, format: 'xlsx' | 'csv'): ParsedSheet[] {
82:   const trimmed = text.trim();
83:   if (!trimmed) return [];
84: 
85:   if (format === 'xlsx' && trimmed.includes('[sheet:')) {
86:     const blocks = trimmed.split(/(?=\[sheet:\s*[^\]]+\])/g);
87:     const sheets: ParsedSheet[] = [];
88:     for (const block of blocks) {
89:       const lines = block.trim().split(/\r?\n/);
90:       if (lines.length === 0) continue;
91:       const headerMatch = /^\[sheet:\s*([^\]]+)\]$/.exec(lines[0]?.trim() ?? '');
92:       const sheetName = headerMatch?.[1]?.trim() || 'Sheet1';
93:       const bodyLines = headerMatch ? lines.slice(1) : lines;
94:       const rows = bodyLines
95:         .filter((l) => l.trim().length > 0 && !l.startsWith('... [truncated'))
96:         .map((l) => (l.includes('\t') ? l.split('\t') : parseCsvLine(l, ',')));
97:       if (rows.length > 0) {
98:         sheets.push({ name: sheetName, rows });
99:       }
100:     }
101:     if (sheets.length > 0) return sheets;
102:   }
103: 
104:   const lines = trimmed.split(/\r?\n/).filter((l) => l.trim().length > 0);
105:   const delimiter = lines[0]?.includes('\t') ? '\t' : ',';
106:   const rows = lines.map((l) =>
107:     delimiter === '\t' ? l.split('\t') : parseCsvLine(l, ','),
108:   );
109:   return rows.length > 0 ? [{ name: 'Sheet1', rows }] : [];
110: }
