128:     if (step.event_type === 'tool_result') {
129:       const toolName = String(step.payload.tool_name ?? '');
130:       if (toolName !== 'generate_document' && toolName !== 'deliver_file') continue;
131:       const res =
132:         typeof step.payload.result === 'object' && step.payload.result !== null
133:           ? (step.payload.result as Record<string, unknown>)
134:           : null;
135:       if (!res || res.ok !== true) continue;
136:       const content =
137:         typeof res.content === 'object' && res.content !== null
138:           ? (res.content as Record<string, unknown>)
139:           : {};
140:       const path =
141:         typeof content.path === 'string'
142:           ? content.path
143:           : typeof res.artifact_ref === 'string'
144:             ? res.artifact_ref
145:             : '';
146:       if (!path) continue;
147:       stepMetaByPath.set(path, {
148:         name: typeof content.name === 'string' ? content.name : undefined,
149:         sha256: typeof content.sha256 === 'string' ? content.sha256 : undefined,
150:         sizeBytes: typeof content.size_bytes === 'number' ? content.size_bytes : undefined,
151:         format: typeof content.format === 'string' ? content.format : undefined,
152:       });
153:     } else if (step.event_type === 'tool_call') {
154:       const toolName = String(step.payload.tool_name ?? '');
155:       if (toolName !== 'generate_document') continue;
156:       const args =
157:         typeof step.payload.arguments === 'object' && step.payload.arguments !== null
158:           ? (step.payload.arguments as Record<string, unknown>)
159:           : {};
160:       const filename = typeof args.filename === 'string' ? args.filename : '';
161:       const bodyText = typeof args.content === 'string' ? args.content : '';
162:       if (filename && bodyText) {
163:         stepMetaByPath.set(`name:${filename}`, {
164:           name: filename,
165:           preview: bodyText,
166:           format: typeof args.format === 'string' ? args.format : undefined,
167:         });
168:       }
169:     }
170:   }
