172:   const items: DeliverableItem[] = [];
173:   const seenPaths = new Set<string>();
174: 
175:   for (const art of artifacts) {
176:     seenPaths.add(art.path);
177:     const baseName = art.path.split('/').pop() ?? art.path;
178:     const stepMeta = stepMetaByPath.get(art.path) ?? stepMetaByPath.get(`name:${baseName}`);
179:     const name = stepMeta?.name ?? baseName;
180:     const format = detectDeliverableFormat(name, stepMeta?.format);
181:     items.push({
182:       id: art.id,
183:       artifactId: art.id,
184:       name,
185:       path: art.path,
186:       sizeBytes: art.size_bytes || stepMeta?.sizeBytes || 0,
187:       sha256: stepMeta?.sha256 ?? null,
188:       preview: art.preview ?? stepMeta?.preview ?? null,
189:       format,
190:     });
191:   }
192: 
193:   for (const [pathKey, meta] of stepMetaByPath.entries()) {
194:     if (pathKey.startsWith('name:') || seenPaths.has(pathKey)) continue;
195:     const baseName = meta.name ?? pathKey.split('/').pop() ?? pathKey;
196:     const nameMeta = stepMetaByPath.get(`name:${baseName}`);
197:     const format = detectDeliverableFormat(baseName, meta.format ?? nameMeta?.format);
198:     items.push({
199:       id: `step-${pathKey}`,
200:       artifactId: null,
201:       name: baseName,
202:       path: pathKey,
203:       sizeBytes: meta.sizeBytes ?? 0,
204:       sha256: meta.sha256 ?? null,
205:       preview: meta.preview ?? nameMeta?.preview ?? null,
206:       format,
207:     });
208:   }
209: 
210:   return items;
211: }
